const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;
if (!reducedMotion) document.documentElement.classList.add('js-motion');
const observer = new IntersectionObserver(entries => entries.forEach(e => { if(e.isIntersecting) { e.target.classList.add('visible'); observer.unobserve(e.target); } }), {threshold:.08});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const theme = document.querySelector('.theme-toggle');
try { document.body.classList.toggle('dark-theme', localStorage.getItem('abi-theme')==='dark'); } catch {}
function updateThemeLabel(){theme.setAttribute('aria-label',document.body.classList.contains('dark-theme')?'Switch to light theme':'Switch to dark theme');}
updateThemeLabel();
theme.addEventListener('click',()=>{document.body.classList.toggle('dark-theme');updateThemeLabel();try{localStorage.setItem('abi-theme',document.body.classList.contains('dark-theme')?'dark':'light');}catch{}window.dispatchEvent(new Event('abi-theme'));});
const menu = document.querySelector('.menu-toggle'), nav = document.querySelector('.site-header nav');
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
const contact = document.querySelector('#contact-dialog');
document.querySelectorAll('[data-contact]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#project-dialog').close();contact.showModal();}));
document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const data = new FormData(event.currentTarget);const body = `Hello ABI team,\n\nI’d like to discuss a ${data.get('service')} project.\n\n${data.get('message')}\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\n\nSent from the ABI website design concept.`;const url=`mailto:requestforquotation@abi-ph.com?subject=${encodeURIComponent('Project inquiry — '+data.get('service'))}&body=${encodeURIComponent(body)}`;const result=document.querySelector('#email-result');result.hidden=false;result.replaceChildren();const p=document.createElement('p');p.textContent='Your inquiry is ready. Open your email app to review and send it to requestforquotation@abi-ph.com.';const a=document.createElement('a');a.href=url;a.className='button dark';a.textContent='Open email app ↗';result.append(p,a);result.setAttribute('role','status');result.scrollIntoView({block:'nearest',behavior:reducedMotion?'instant':'smooth'});});
const projects={alternergy:{name:'Alternergy',description:'An office fit-out for a Philippine renewable energy pioneer. ABI’s published portfolio presents this workspace as part of its integrated design and construction practice.',url:'https://abi-ph.com/project/alternergy/'},etiqa:{name:'Etiqa',description:'A workplace for a Southeast Asian insurance provider. Explore ABI’s published office fit-out project and its approach to creating spaces around the people who use them.',url:'https://abi-ph.com/project/etiqa/'},afni:{name:'AFNI',description:'An office fit-out for a customer engagement business. A project from ABI’s published portfolio of workplaces that support connection and collaboration.',url:'https://abi-ph.com/project/afni/'}};
document.querySelectorAll('[data-project]').forEach(card=>card.addEventListener('click',()=>{const key=card.dataset.project,project=projects[key];document.querySelector('#detail-image').src=`assets/${key}.webp`;document.querySelector('#detail-image').alt=`${project.name} office fit-out by ABI`;document.querySelector('#detail-title').textContent=project.name;document.querySelector('#detail-description').textContent=project.description;document.querySelector('#detail-link').href=project.url;document.querySelector('#project-dialog').showModal();}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});let count=0;document.querySelectorAll('.project-card').forEach(card=>{const visible=button.dataset.filter==='all'||card.dataset.category===button.dataset.filter;card.hidden=!visible;if(visible)count++;});document.querySelector('.filter-empty').hidden=count>0;}));
document.querySelectorAll('.services details').forEach(details=>details.addEventListener('toggle',()=>{if(details.open)document.querySelectorAll('.services details').forEach(other=>{if(other!==details)other.open=false;});}));
const demos=[{name:'The Greenhouse Office',progress:68,days:24,status:'On track',phase:2,date:'Nov 09, 2026',dates:['Sep 04','Sep 18','Oct 12','Nov 09'],update:'Level 2 partition works approved',updated:'Today, 9:41 AM',description:'A sample office fit-out with open workspaces, meeting rooms, and collaborative areas.'},{name:'Northline Commercial Hub',progress:38,days:58,status:'On track',phase:1,date:'Dec 13, 2026',dates:['Aug 28','Oct 02','Nov 16','Dec 13'],update:'Structural drawings issued for review',updated:'Today, 10:15 AM',description:'A sample commercial construction project from design through structural and finishing works.'},{name:'Studio Twenty Eight',progress:92,days:7,status:'Final checks',phase:3,date:'Oct 23, 2026',dates:['Aug 10','Aug 24','Sep 21','Oct 23'],update:'Final walkthrough scheduled',updated:'Yesterday, 3:20 PM',description:'A sample creative studio fit-out approaching completion and client handover.'}];
let currentProject=0,currentView='overview';const phaseNames=['Discovery','Design','Construction','Handover'];
function renderDashboard(){const d=demos[currentProject],view=document.querySelector('#dashboard-view');
if(currentView==='overview'){view.innerHTML=`<div class="dash-metrics"><div class="metric"><span>Overall progress <span>↗</span></span><strong>${d.progress}<span style="font-size:14px">%</span></strong><small>Every detail, coming together.</small><div class="mini-progress"><i style="width:${d.progress}%"></i></div></div><div class="metric"><span>Days to completion <span>◷</span></span><strong>${d.days}<span style="font-size:11px;letter-spacing:0"> days</span></strong><small>Target: ${d.date}</small></div><div class="metric"><span>Project health <span>⟡</span></span><strong class="on-track"><span class="status-dot"></span> ${d.status}</strong><small>Moving toward your next milestone.</small></div></div><div class="dash-lower"><div class="dash-panel"><div class="dash-panel-title">Your journey <small>FROM VISION TO REALITY</small></div><div class="phases">${phaseNames.map((p,i)=>`<div class="phase ${i<d.phase?'done':i===d.phase?'current':''}"><i>${i<d.phase?'✓':i===d.phase?'•':i+1}</i><span>${p}</span><small>${d.dates[i]}</small></div>`).join('')}</div></div><div class="dash-panel"><div class="dash-panel-title">Latest update <small>↗</small></div><div class="activity-row"><i>✓</i><div>${d.update}<small>${d.updated} · Demo project team</small></div></div></div></div>`;
}else if(currentView==='timeline'){view.innerHTML=`<div class="timeline-list">${phaseNames.map((p,i)=>`<div class="timeline-item"><span class="timeline-icon">${i<d.phase?'✓':i===d.phase?'◉':'○'}</span><div><h4>${p}</h4><p>${['Establishing the brief, goals, and project scope.','Developing plans, materials, and specifications.','Bringing the approved design to life on site.','Final checks, walkthrough, and turnover.'][i]}</p></div><small>${d.dates[i]} · ${i<d.phase?'Complete':i===d.phase?'In progress':'Upcoming'}</small></div>`).join('')}</div>`;
}else{view.innerHTML=`<div>${['Project brief','Milestone schedule','Progress summary'].map((name,i)=>`<div class="document-row"><span>▤</span><div><h4>${name}</h4><small>Sample document · TXT · ${d.name}</small></div><button data-download="${i}">Download ↓</button></div>`).join('')}</div>`;view.querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.download),names=['Project brief','Milestone schedule','Progress summary'];const content=`ABI WEBSITE CONCEPT — ILLUSTRATIVE DOCUMENT\n\n${names[i]}\nProject: ${d.name}\n\n${i===0?d.description:i===1?phaseNames.map((p,n)=>`${p}: ${d.dates[n]}, 2026`).join('\n'):`Overall progress: ${d.progress}%\nStatus: ${d.status}\nTarget completion: ${d.date}\nLatest update: ${d.update}`}\n\nThis is sample data for a website design demonstration. It is not an actual ABI project record.`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=`ABI-demo-${names[i].toLowerCase().replaceAll(' ','-')}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}));}}
document.querySelector('#project-select').addEventListener('change',e=>{currentProject=Number(e.target.value);renderDashboard();});document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{currentView=b.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('selected',n===b));renderDashboard();}));renderDashboard();
